mapper.select:
select j.job_id, j.request_id, j.export_type, j.file_format, j.status, j.progress,
       j.total_rows, j.processed_rows, j.file_name, j.file_size, j.checksum,
       j.retry_count, j.error_code, j.error_message, j.operator_id, e.name as operator_name,
       j.started_at, j.finished_at, j.expires_at, j.create_time, j.update_time
from export_job j

    force index (idx_export_operator_list)
    force index (idx_export_admin_list)

left join employee e on e.id = j.operator_id

    and j.operator_id = #{visibleOperatorId}
    and j.export_type = #{query.exportType}
    and j.file_format = #{query.fileFormat}
    and j.status = #{query.status}
    and j.operator_id = #{query.operatorId}
    and j.create_time >= #{query.startTime}
    and j.create_time <= #{query.endTime}

order by j.create_time desc, j.job_id desc

select job_id from (
    select job_id, next_retry_at as ready_at from export_job force index (idx_export_ready)
    where status = 'PENDING' and next_retry_at <= #{now}
    union all
    select job_id, lease_until as ready_at from export_job force index (idx_export_lease)
    where status = 'RUNNING' and lease_until <= #{now}
) ready_jobs
order by ready_at, job_id
limit #{limit}

mapper.update:
update export_job
set status = 'RUNNING', lease_owner = #{leaseOwner}, lease_until = #{leaseUntil},
    progress = 0, processed_rows = 0, started_at = coalesce(started_at, #{now}), update_time = #{now}
where job_id = #{jobId}
  and ((status = 'PENDING' and next_retry_at <= #{now})
    or (status = 'RUNNING' and lease_until <= #{now}))

update export_job set processed_rows = #{processedRows}, progress = #{progress},
    lease_until = #{leaseUntil}, update_time = #{now}
where job_id = #{jobId} and status = 'RUNNING' and lease_owner = #{leaseOwner}

update export_job
set status = 'SUCCEEDED', progress = 100, processed_rows = #{processedRows},
    file_path = #{filePath}, file_name = #{fileName}, file_size = #{fileSize}, checksum = #{checksum},
    lease_owner = null, lease_until = null, error_code = null, error_message = null,
    finished_at = #{finishedAt}, expires_at = #{expiresAt}, update_time = #{finishedAt}
where job_id = #{jobId} and status = 'RUNNING' and lease_owner = #{leaseOwner}

update export_job
set status = 'PENDING', retry_count = #{retryCount}, next_retry_at = #{nextRetryAt},
    lease_owner = null, lease_until = null, error_code = #{errorCode}, error_message = #{errorMessage},
    update_time = #{now}
where job_id = #{jobId} and status = 'RUNNING' and lease_owner = #{leaseOwner}

update export_job
set status = 'FAILED', retry_count = #{retryCount}, lease_owner = null, lease_until = null,
    error_code = #{errorCode}, error_message = #{errorMessage}, finished_at = #{now}, update_time = #{now}
where job_id = #{jobId} and status = 'RUNNING' and lease_owner = #{leaseOwner}

mapper.select:
select job_id from export_job
where status = 'SUCCEEDED' and expires_at <= #{now}
order by expires_at, job_id
limit #{limit}
